export async function run({ page, name, status }: { page: import('@playwright/test').Page; name: string; status: string }): Promise<{ name: string; status: string; confirmed: true }> {
  if (name !== 'alpha') {
    throw new Error(`confirm: expected name "alpha" but received "${name}"`);
  }
  if (status !== 'done-alpha') {
    throw new Error(`confirm: expected status "done-alpha" but received "${status}"`);
  }
  const heading = page.getByRole('heading', { name: 'alpha' });
  const headingText = await heading.textContent();
  if (headingText === null || !headingText.includes('alpha')) {
    throw new Error(`confirm: heading "alpha" not found, got "${headingText}"`);
  }
  const statusLocator = page.getByRole('status');
  const actualStatus = ((await statusLocator.textContent()) ?? '').trim();
  if (actualStatus !== 'done-alpha') {
    throw new Error(`confirm: role=status expected "done-alpha" but found "${actualStatus}"`);
  }
  if (actualStatus !== status) {
    throw new Error(`confirm: status argument "${status}" does not match page role=status "${actualStatus}"`);
  }
  return { name, status, confirmed: true as const };
}

import { test, expect } from '@playwright/test';
import { run } from '@lib/m12-confirm';

test('confirm bound outcome without page mutation', async ({ page }) => {
  await page.setContent('<h1>alpha</h1><div role="status">done-alpha</div>');
  const result = await run({ page, name: 'alpha', status: 'done-alpha' });
  expect(result).toEqual({ name: 'alpha', status: 'done-alpha', confirmed: true });
  await expect(page.getByRole('heading', { name: 'alpha' })).toBeVisible();
  await expect(page.getByRole('status')).toHaveText('done-alpha');
});

